app = FastAPI(title='VivaProof', docs_url=None, redoc_url=None)
requests = deque()

@app.middleware('http')
async def secure_headers(request, call_next):
    response = await call_next(request)
    response.headers.update({'Cache-Control':'no-store', 'X-Content-Type-Options':'nosniff', 'Referrer-Policy':'no-referrer'})
    return response

@app.get('/health')
async def health():
    return {'status':'ok', 'backend':'FastAPI'}

async def mint_token():
    key = os.environ.get('ASSEMBLYAI_API_KEY')
    if not key:
        raise ValueError('Live voice is not configured. Explore the sample walkthrough instead.')
    now = time.monotonic()
    while requests and now - requests[0] > 3600:
        requests.popleft()
    if len(requests) >= int(os.environ.get('MAX_SESSIONS_PER_HOUR', '20')):
        raise OverflowError('Demo session limit reached. Please try later.')
    requests.append(now)
    async with httpx.AsyncClient(timeout=20) as client:
        response = await client.get('https://agents.assemblyai.com/v1/token', params={'product':'voice_agent', 'expires_in_seconds':60, 'max_session_duration_seconds':300}, headers={'Authorization':'Bearer '+key})
        response.raise_for_status()
        return response.json()['token']

@app.websocket('/voice')
async def voice(browser: WebSocket):
    # Block cross-site use of this account's credits. Browser must be same-origin.
    origin = browser.headers.get('origin', '')
    host = browser.headers.get('host', '')
    if origin not in ('https://'+host, 'http://'+host):
        await browser.close(code=1008)
        return
    await browser.accept()
    tasks = []
    try:
        token = await mint_token()
        async with websockets.connect('wss://agents.assemblyai.com/v1/ws?token='+token, max_size=2**20, open_timeout=20) as provider:
            async def upstream():
                while True:
                    data = await browser.receive_text()
                    if len(data) > 2**20:
                        raise ValueError('Audio frame too large.')
                    await provider.send(data)
            async def downstream():
                async for data in provider:
                    await browser.send_text(data)
            tasks = [asyncio.create_task(upstream()), asyncio.create_task(downstream())]
            done, pending = await asyncio.wait(tasks, timeout=310, return_when=asyncio.FIRST_COMPLETED)
            for task in done:
                task.result()
    except (ValueError, OverflowError) as error:
        try: await browser.send_json({'type':'session.error', 'message':str(error), 'code':'unavailable'})
        except Exception: pass
    except WebSocketDisconnect:
        pass
    except Exception:
        try: await browser.send_json({'type':'session.error', 'message':'Voice service unavailable. Please try again.', 'code':'unavailable'})
        except Exception: pass
    finally:
        for task in tasks:
            if not task.done(): task.cancel()
        if tasks: await asyncio.gather(*tasks, return_exceptions=True)
        try: await browser.close()
        except Exception: pass

@app.get('/')
async def index():
    return Response(ASSETS['index.html'], media_type='text/html')

@app.get('/{filename}')
async def asset(filename: str):
    if filename not in ASSETS:
        return JSONResponse({'error':'Not found'}, status_code=404)
    kind = {'html':'text/html','js':'text/javascript','css':'text/css'}[filename.rsplit('.',1)[-1]]
    return Response(ASSETS[filename], media_type=kind)

if __name__ == '__main__':
    uvicorn.run(app, host='0.0.0.0', port=int(os.environ.get('PORT','3000')))
